 27	package com.pousadamarealta.api;
 28	
 29	import io.javalin.Javalin;
 30	import io.javalin.http.Context;
 31	import java.math.BigDecimal;
 32	import java.sql.SQLException;
 33	import java.time.LocalDate;
 34	import java.time.YearMonth;
 35	import java.time.format.DateTimeFormatter;
 36	import java.util.HashMap;
 37	import java.util.List;
 38	import java.util.Map;
 39	import com.fasterxml.jackson.databind.JsonNode;
 40	import com.fasterxml.jackson.databind.ObjectMapper;
 41	import com.pousadamarealta.dao.RoomDAO;
 42	import com.pousadamarealta.models.*;
 43	import com.pousadamarealta.service.*;
 44	
 45	public class ApiRoutes {
 46	    private static final ObjectMapper mapper = new ObjectMapper();
 47	
 48	    public static void setupRoutes(Javalin app) {
 49	        app.get("/rooms", ApiRoutes::getRooms);
 50	        app.post("/reservations", ApiRoutes::createReservation);
 51	        app.get("/reservations/{id}", ApiRoutes::getReservation);
 52	        app.post("/reservations/{id}/confirmation", ApiRoutes::confirmReservation);
 53	        app.post("/reservations/{id}/cancellation", ApiRoutes::cancelReservation);
 54	        app.post("/reservations/{id}/check-in", ApiRoutes::checkIn);
 55	        app.post("/reservations/{id}/check-out", ApiRoutes::checkOut);
 56	        app.get("/reservations/{id}/document", ApiRoutes::getDocument);
 57	        app.get("/messages", ApiRoutes::getMessages);
 58	        app.get("/reports/occupancy", ApiRoutes::getOccupancyReport);
 59	        app.get("/reports/revenue", ApiRoutes::getRevenueReport);
 60	    }
 61	
 62	    private static void getRooms(Context ctx) throws SQLException {
 63	        List<Room> rooms = RoomDAO.getAllRooms();
 64	        List<Map<String, Object>> response = rooms.stream().map(room -> {
 65	            Map<String, Object> map = new HashMap<>();
 66	            map.put("number", room.number());
 67	            map.put("type", room.type().name());
 68	            map.put("capacity", room.capacity());
 69	            map.put("nightlyRate", room.nightlyRate().doubleValue());
 70	            return map;
 71	        }).toList();
 72	        ctx.json(response);
 73	    }
 74	
 75	    private static void createReservation(Context ctx) throws SQLException {
 76	        try {
 77	            JsonNode body = mapper.readTree(ctx.body());
 78	
 79	            if (body.get("roomNumber") == null || body.get("guestName") == null ||
 80	                body.get("guestEmail") == null || body.get("guestCpf") == null ||
 81	                body.get("checkIn") == null || body.get("checkOut") == null ||
 82	                body.get("guests") == null || body.get("ratePlan") == null) {
 83	                ctx.status(400);
 84	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid request"));
 85	                return;
 86	            }
 87	
 88	            int roomNumber = body.get("roomNumber").asInt();
 89	            String guestName = body.get("guestName").asText();
 90	            String guestEmail = body.get("guestEmail").asText();
 91	            String guestCpf = body.get("guestCpf").asText();
 92	            LocalDate checkIn = LocalDate.parse(body.get("checkIn").asText());
 93	            LocalDate checkOut = LocalDate.parse(body.get("checkOut").asText());
 94	            int guests = body.get("guests").asInt();
 95	            RatePlan ratePlan = RatePlan.valueOf(body.get("ratePlan").asText());
 96	
 97	            if (guests < 1 || checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
 98	                ctx.status(400);
 99	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid request"));
100	                return;
101	            }
102	
103	            Room room = RoomDAO.getRoomByNumber(roomNumber);
104	            if (room == null) {
105	                ctx.status(404);
106	                ctx.json(Map.of("error", "ROOM_NOT_FOUND", "message", "Room not found"));
107	                return;
108	            }
109	
110	            if (guests > room.capacity()) {
111	                ctx.status(422);
112	                ctx.json(Map.of("error", "CAPACITY_EXCEEDED", "message", "Capacity exceeded"));
113	                return;
114	            }
115	
116	            Reservation reservation = ReservationService.createReservation(roomNumber, guestName, guestEmail,
117	                    guestCpf, checkIn, checkOut, guests, ratePlan);
118	
119	            if (reservation == null) {
120	                ctx.status(409);
121	                ctx.json(Map.of("error", "ROOM_UNAVAILABLE", "message", "Room not available"));
122	                return;
123	            }
124	
125	            ctx.status(201);
126	            ctx.json(reservationToJson(reservation));
127	        } catch (Exception e) {
128	            ctx.status(400);
129	            ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid request"));
130	        }
131	    }
132	
133	    private static void getReservation(Context ctx) throws SQLException {
134	        int id = ctx.pathParamAsClass("id", Integer.class).get();
135	        Reservation reservation = ReservationService.getReservation(id);
136	        if (reservation == null) {
137	            ctx.status(404);
138	            ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
139	            return;
140	        }
141	        ctx.json(reservationToJson(reservation));
142	    }
143	
144	    private static void confirmReservation(Context ctx) throws SQLException {
145	        int id = ctx.pathParamAsClass("id", Integer.class).get();
146	        Reservation reservation = ReservationService.confirmReservation(id);
147	        if (reservation == null) {
148	            ctx.status(409);
149	            ctx.json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", "Operation not allowed"));
150	            return;
151	        }
152	        ctx.json(reservationToJson(reservation));
153	    }
154	
155	    private static void cancelReservation(Context ctx) throws SQLException {
156	        int id = ctx.pathParamAsClass("id", Integer.class).get();
157	        Reservation reservation = ReservationService.cancelReservation(id);
158	        if (reservation == null) {
159	            ctx.status(409);
160	            ctx.json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", "Operation not allowed"));
161	            return;
162	        }
163	        ctx.json(reservationToJson(reservation));
164	    }
165	
166	    private static void checkIn(Context ctx) throws SQLException {
167	        int id = ctx.pathParamAsClass("id", Integer.class).get();
168	        Reservation reservation = ReservationService.checkIn(id);
169	        if (reservation == null) {
170	            ctx.status(409);
171	            ctx.json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", "Operation not allowed"));
172	            return;
173	        }
174	        ctx.json(reservationToJson(reservation));
175	    }
176	
177	    private static void checkOut(Context ctx) throws SQLException {
178	        int id = ctx.pathParamAsClass("id", Integer.class).get();
179	        Reservation reservation = ReservationService.checkOut(id);
180	        if (reservation == null) {
181	            ctx.status(409);
182	            ctx.json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", "Operation not allowed"));
183	            return;
184	        }
185	
186	        Receipt receipt = ReceiptFormatter.toReceipt(reservation.id(), reservation.guestName(),
187	                reservation.guestCpf(), reservation.roomNumber(),
188	                RoomDAO.getRoomByNumber(reservation.roomNumber()).type(),
189	                reservation.checkIn(), reservation.checkOut(),
190	                reservation.nights(), reservation.subtotal(),
191	                reservation.discount(), reservation.total());
192	
193	        ctx.json(receiptToJson(receipt));
194	    }
195	
196	    private static void getDocument(Context ctx) throws SQLException {
197	        int id = ctx.pathParamAsClass("id", Integer.class).get();
198	        Reservation reservation = ReservationService.getDocument(id);
199	        if (reservation == null) {
200	            ctx.status(404);
201	            ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
202	            return;
203	        }
204	
205	        if (reservation.amountPaid().compareTo(BigDecimal.ZERO) <= 0) {
206	            ctx.status(404);
207	            ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Document not available"));
208	            return;
209	        }
210	
211	        Receipt receipt = ReceiptFormatter.toReceipt(reservation.id(), reservation.guestName(),
212	                reservation.guestCpf(), reservation.roomNumber(),
213	                RoomDAO.getRoomByNumber(reservation.roomNumber()).type(),
214	                reservation.checkIn(), reservation.checkOut(),
215	                reservation.nights(), reservation.subtotal(),
216	                reservation.discount(), reservation.total());
217	
218	        ctx.json(receiptToJson(receipt));
219	    }
220	
221	    private static void getMessages(Context ctx) throws SQLException {
222	        List<Message> messages = MessageService.getAllMessages();
223	        List<Map<String, Object>> response = messages.stream().map(msg -> {
224	            Map<String, Object> map = new HashMap<>();
225	            map.put("id", msg.id());
226	            map.put("channel", msg.channel().name());
227	            map.put("to", msg.to());
228	            map.put("subject", msg.subject());
229	            map.put("body", msg.body());
230	            map.put("status", msg.status().name());
231	            return map;
232	        }).toList();
233	        ctx.json(response);
234	    }
235	
236	    private static void getOccupancyReport(Context ctx) throws SQLException {
237	        String dateStr = ctx.queryParam("date");
238	        if (dateStr == null || dateStr.isEmpty()) {
239	            ctx.status(400);
240	            ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Date parameter required"));
241	            return;
242	        }
243	
244	        try {
245	            LocalDate date = LocalDate.parse(dateStr);
246	            String report = ReportService.generateOccupancyReport(date);
247	            ctx.contentType("text/csv; charset=utf-8");
248	            ctx.result(report);
249	        } catch (Exception e) {
250	            ctx.status(400);
251	            ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid date format"));
252	        }
253	    }
254	
255	    private static void getRevenueReport(Context ctx) throws SQLException {
256	        String monthStr = ctx.queryParam("month");
257	        if (monthStr == null || monthStr.isEmpty()) {
258	            ctx.status(400);
259	            ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Month parameter required"));
260	            return;
261	        }
262	
263	        try {
264	            YearMonth month = YearMonth.parse(monthStr);
265	            String report = ReportService.generateRevenueReport(month);
266	            ctx.contentType("text/csv; charset=utf-8");
267	            ctx.result(report);
268	        } catch (Exception e) {
269	            ctx.status(400);
270	            ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid month format"));
271	        }
272	    }
273	
274	    private static Map<String, Object> reservationToJson(Reservation r) {
275	        Map<String, Object> map = new HashMap<>();
276	        map.put("id", r.id());
277	        map.put("roomNumber", r.roomNumber());
278	        map.put("guestName", r.guestName());
279	        map.put("guestEmail", r.guestEmail());
280	        map.put("guestCpf", r.guestCpf());
281	        map.put("checkIn", r.checkIn().toString());
282	        map.put("checkOut", r.checkOut().toString());
283	        map.put("guests", r.guests());
284	        map.put("ratePlan", r.ratePlan().name());
285	        map.put("nights", r.nights());
286	        map.put("subtotal", r.subtotal().doubleValue());
287	        map.put("discount", r.discount().doubleValue());
288	        map.put("total", r.total().doubleValue());
289	        map.put("status", r.status().name());
290	        map.put("amountPaid", r.amountPaid().doubleValue());
291	        map.put("refund", r.refund() != null ? r.refund().doubleValue() : null);
292	        return map;
293	    }
294	
295	    private static Map<String, Object> receiptToJson(Receipt r) {
296	        Map<String, Object> map = new HashMap<>();
297	        map.put("title", r.title());
298	        map.put("reservationId", r.reservationId());
299	        map.put("guestName", r.guestName());
300	        map.put("guestCpf", r.guestCpf());
301	        map.put("roomNumber", r.roomNumber());
302	        map.put("roomType", r.roomType().name());
303	        map.put("checkIn", r.checkIn().toString());
304	        map.put("checkOut", r.checkOut().toString());
305	        map.put("nights", r.nights());
306	        map.put("subtotal", r.subtotal().doubleValue());
307	        map.put("discount", r.discount().doubleValue());
308	        map.put("total", r.total().doubleValue());
309	        return map;
310	    }
311	}

