 53	import java.math.BigDecimal;
 54	import java.text.NumberFormat;
 55	import java.time.LocalDate;
 56	import java.time.format.DateTimeFormatter;
 57	import java.util.Locale;
 58	import com.pousadamarealta.models.Receipt;
 59	import com.pousadamarealta.models.Reservation;
 60	import com.pousadamarealta.models.RoomType;
 61	
 62	public class ReceiptFormatter {
 63	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 64	    private static final Locale PT_BR = new Locale("pt", "BR");
 65	    private static final NumberFormat CURRENCY_FORMAT = NumberFormat.getInstance(PT_BR);
 66	
 67	    static {
 68	        CURRENCY_FORMAT.setMinimumFractionDigits(2);
 69	        CURRENCY_FORMAT.setMaximumFractionDigits(2);
 70	    }
 71	
 72	    public static String formatReceipt(Receipt receipt) {
 73	        StringBuilder sb = new StringBuilder();
 74	        sb.append("Comprovante de reserva nº ").append(receipt.reservationId()).append("\n");
 75	        sb.append("Hóspede: ").append(receipt.guestName()).append(" (CPF ").append(formatCpf(receipt.guestCpf())).append(")\n");
 76	        sb.append("Quarto: ").append(receipt.roomNumber()).append(" (").append(receipt.roomType()).append(")\n");
 77	        sb.append("Entrada: ").append(DATE_FORMATTER.format(receipt.checkIn())).append(" | ");
 78	        sb.append("Saída: ").append(DATE_FORMATTER.format(receipt.checkOut())).append(" | ");
 79	        sb.append(receipt.nights()).append(receipt.nights() == 1 ? " diária" : " diárias").append("\n");
 80	        sb.append("Diárias: ").append(formatCurrency(receipt.subtotal())).append("\n");
 81	
 82	        if (receipt.discount().compareTo(BigDecimal.ZERO) > 0) {
 83	            sb.append("Desconto: ").append(formatCurrency(receipt.discount())).append("\n");
 84	        }
 85	
 86	        sb.append("Total: ").append(formatCurrency(receipt.total()));
 87	        return sb.toString();
 88	    }
 89	
 90	    public static String formatConfirmationEmail(String guestName, Receipt receipt) {
 91	        StringBuilder sb = new StringBuilder();
 92	        sb.append("Olá, ").append(guestName).append("!\n\n");
 93	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
 94	        sb.append(formatReceipt(receipt)).append("\n\n");
 95	        sb.append("A entrada é a partir das 14h, e a saída, até as 12h.\n");
 96	        sb.append("Até breve!");
 97	        return sb.toString();
 98	    }
 99	
100	    public static Receipt toReceipt(int reservationId, String guestName, String guestCpf, int roomNumber,
101	                                    RoomType roomType, LocalDate checkIn, LocalDate checkOut, int nights,
102	                                    BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
103	        return new Receipt("Comprovante de reserva", reservationId, guestName, guestCpf, roomNumber,
104	                          roomType, checkIn, checkOut, nights, subtotal, discount, total);
105	    }
106	
107	    private static String formatCurrency(BigDecimal value) {
108	        String formatted = CURRENCY_FORMAT.format(value);
109	        return "R$ " + formatted;
110	    }
111	
112	    private static String formatCpf(String cpf) {
113	        if (cpf == null || cpf.length() < 11) {
114	            return cpf;
115	        }
116	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
117	               cpf.substring(6, 9) + "-" + cpf.substring(9);
118	    }
119	}
