153	            month.getYear(), month.getMonthValue());
154	
155	        StringBuilder csv = new StringBuilder();
156	        csv.append("reservation,room,check_in,check_out,status,amount\n");
157	
158	        java.math.BigDecimal total = java.math.BigDecimal.ZERO;
159	        for (Reservation res : reservations) {
160	            csv.append(res.id()).append(",");
161	            csv.append(res.roomNumber()).append(",");
162	            csv.append(res.checkIn()).append(",");
163	            csv.append(res.checkOut()).append(",");
164	            csv.append(res.status()).append(",");
165	
166	            java.math.BigDecimal amount = res.amountPaid();
167	            if (res.refund() != null && res.refund().compareTo(java.math.BigDecimal.ZERO) > 0) {
168	                amount = amount.subtract(res.refund());
169	            }
170	
171	            csv.append(String.format(java.util.Locale.US, "%.2f", amount)).append("\n");
172	            total = total.add(amount);
173	        }
174	
175	        csv.append("total,,,,").append(String.format(java.util.Locale.US, "%.2f", total));
176	        return csv.toString();
177	    }
178	}
