310	import java.util.regex.Pattern;
311	
312	public class EmailValidator {
313	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@]+@[^@]+\\.[^@]+$");
314	
315	    public static boolean isValid(String email) {
316	        if (email == null || email.isEmpty()) {
317	            return false;
318	        }
319	
320	        int atIndex = email.indexOf('@');
321	        if (atIndex <= 0 || email.indexOf('@', atIndex + 1) != -1) {
322	            return false;
323	        }
324	
325	        String afterAt = email.substring(atIndex + 1);
326	        return afterAt.contains(".") && !afterAt.startsWith(".") && !afterAt.endsWith(".");
327	    }
328	}
