189	public class ReservationService {
190	    public static Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
191	                                                 LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan)
192	            throws SQLException {
193	        Room room = RoomDAO.getRoomByNumber(roomNumber);
194	        if (room == null) {
195	            return null;
196	        }
197	
198	        if (!ReservationDAO.isRoomAvailable(roomNumber, checkIn, checkOut)) {
199	            return null;
200	        }
201	
202	        if (guests < 1 || guests > room.capacity()) {
203	            return null;
204	        }
205	
206	        int nights = PricingCalculator.calculateNights(checkIn, checkOut);
207	        if (nights <= 0) {
208	            return null;
209	        }
210	
211	        BigDecimal nightlyRate = room.nightlyRate();
212	        BigDecimal subtotal = BigDecimal.ZERO;
213	
214	        for (int i = 0; i < nights; i++) {
215	            LocalDate nightDate = checkIn.plusDays(i);
216	            BigDecimal rate = PricingCalculator.calculateNightlyRate(nightlyRate, nightDate);
217	            subtotal = subtotal.add(rate);
218	        }
219	        subtotal = com.pousadamarealta.util.PriceRounding.round(subtotal);
220	
221	        BigDecimal discount = PricingCalculator.calculateDiscount(subtotal, ratePlan);
222	        BigDecimal total = PricingCalculator.calculateTotal(subtotal, discount);
223	
224	        return ReservationDAO.create(roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut,
225	                                     guests, ratePlan, nights, subtotal, discount, total);
226	    }
227	
228	    public static Reservation getReservation(int id) throws SQLException {
229	        return ReservationDAO.getById(id);
230	    }
231	
232	    public static Reservation confirmReservation(int id) throws SQLException {
233	        Reservation reservation = ReservationDAO.getById(id);
234	        if (reservation == null || reservation.status() != ReservationStatus.PENDING) {
235	            return null;
236	        }
237	
238	        ReservationDAO.updateStatusAndAmountPaid(id, ReservationStatus.CONFIRMED, reservation.total());
239	
240	        String emailBody = ReceiptFormatter.formatConfirmationEmail(
241	            reservation.guestName(),
242	            ReceiptFormatter.toReceipt(id, reservation.guestName(), reservation.guestCpf(),
243	                                      reservation.roomNumber(),
244	                                      RoomDAO.getRoomByNumber(reservation.roomNumber()).type(),
245	                                      reservation.checkIn(), reservation.checkOut(),
246	                                      reservation.nights(), reservation.subtotal(),
247	                                      reservation.discount(), reservation.total())
248	        );
249	
250	        MessageService.sendEmail(reservation.guestEmail(),
251	                                "Reserva confirmada - Pousada Maré Alta",
252	                                emailBody);
253	
254	        return ReservationDAO.getById(id);
255	    }
256	
257	    public static Reservation checkIn(int id) throws SQLException {
258	        Reservation reservation = ReservationDAO.getById(id);
259	        if (reservation == null || reservation.status() != ReservationStatus.CONFIRMED) {
260	            return null;
261	        }
262	
263	        ReservationDAO.updateStatus(id, ReservationStatus.CHECKED_IN);
264	        return ReservationDAO.getById(id);
265	    }
266	
267	    public static Reservation checkOut(int id) throws SQLException {
268	        Reservation reservation = ReservationDAO.getById(id);
269	        if (reservation == null || reservation.status() != ReservationStatus.CHECKED_IN) {
270	            return null;
271	        }
272	
273	        ReservationDAO.updateStatus(id, ReservationStatus.CHECKED_OUT);
274	        return ReservationDAO.getById(id);
275	    }
276	
277	    public static Reservation cancelReservation(int id) throws SQLException {
278	        Reservation reservation = ReservationDAO.getById(id);
279	        if (reservation == null ||
280	            (reservation.status() != ReservationStatus.PENDING &&
281	             reservation.status() != ReservationStatus.CONFIRMED)) {
282	            return null;
283	        }
284	
285	        BigDecimal refund = calculateRefund(reservation);
286	        ReservationDAO.updateStatus(id, ReservationStatus.CANCELLED);
287	        ReservationDAO.updateRefund(id, refund);
288	
289	        return ReservationDAO.getById(id);
290	    }
291	
292	    private static BigDecimal calculateRefund(Reservation reservation) {
293	        if (reservation.status() == ReservationStatus.PENDING) {
294	            return BigDecimal.ZERO;
295	        }
296	
297	        if (reservation.ratePlan() == RatePlan.NON_REFUNDABLE) {
298	            return BigDecimal.ZERO;
299	        }
300	
301	        return reservation.amountPaid();
302	    }
303	
304	    public static Reservation getDocument(int id) throws SQLException {
305	        return ReservationDAO.getById(id);
306	    }
307	}
