340	
341	import java.math.BigDecimal;
342	import java.time.LocalDate;
343	import com.pousadamarealta.models.RatePlan;
344	
345	public class PricingCalculator {
346	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
347	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
348	
349	    public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
350	        if (isHighSeason(date)) {
351	            return PriceRounding.round(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
352	        }
353	        return baseRate;
354	    }
355	
356	    public static BigDecimal calculateSubtotal(BigDecimal nightlyRate, int nights) {
357	        return PriceRounding.round(nightlyRate.multiply(new BigDecimal(nights)));
358	    }
359	
360	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
361	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
362	            return PriceRounding.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
363	        }
364	        return BigDecimal.ZERO;
365	    }
366	
367	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
368	        return PriceRounding.round(subtotal.subtract(discount));
369	    }
370	
371	    private static boolean isHighSeason(LocalDate date) {
372	        int month = date.getMonthValue();
373	        int day = date.getDayOfMonth();
374	
375	        if (month == 7) return true;
376	        if (month == 12 && day >= 15) return true;
377	        if (month == 1) return true;
378	        if (month == 2) return true;
379	        return false;
380	    }
381	
382	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
383	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
384	    }
385	}

