 21	        instance = new Database(dbUrl, dbUser, dbPassword);
 22	        instance.createTables();
 23	    }
 24	
 25	    public static Database getInstance() {
 26	        if (instance == null) {
 27	            throw new IllegalStateException("Database not initialized");
 28	        }
 29	        return instance;
 30	    }
