 36	    private void createTables() {
 37	        try (Connection conn = getConnection(); Statement stmt = conn.createStatement()) {
 38	            stmt.execute("""
 39	                CREATE TABLE IF NOT EXISTS rooms (
 40	                    number INT PRIMARY KEY,
 41	                    type VARCHAR(20) NOT NULL,
 42	                    capacity INT NOT NULL,
 43	                    nightly_rate NUMERIC(10, 2) NOT NULL
 44	                )
 45	                """);
 46	
 47	            stmt.execute("""
 48	                CREATE TABLE IF NOT EXISTS reservations (
 49	                    id SERIAL PRIMARY KEY,
 50	                    room_number INT NOT NULL REFERENCES rooms(number),
 51	                    guest_name VARCHAR(255) NOT NULL,
 52	                    guest_email VARCHAR(255) NOT NULL,
