 63	                    amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
 64	                    refund NUMERIC(10, 2)
 65	                )
 66	                """);
 67	
 68	            stmt.execute("""
 69	                CREATE TABLE IF NOT EXISTS messages (
 70	                    id SERIAL PRIMARY KEY,
 71	                    channel VARCHAR(20) NOT NULL,
 72	                    recipient VARCHAR(255) NOT NULL,
 73	                    subject VARCHAR(255) NOT NULL,
 74	                    body TEXT NOT NULL,
 75	                    status VARCHAR(20) NOT NULL
 76	                )
 77	                """);
 78	
 79	            initializeRooms(conn);
 80	        } catch (SQLException e) {
 81	            throw new RuntimeException("Failed to create tables", e);
 82	        }
 83	    }
