 10	public class PricingIntegrationTest {
 11	    @Test
 12	    public void testStandardRoomHighSeason() {
 13	        BigDecimal baseRate = new BigDecimal("249.90");
 14	        LocalDate checkIn = LocalDate.of(2027, 7, 10);
 15	        LocalDate checkOut = LocalDate.of(2027, 7, 12);
 16	
 17	        int nights = PricingCalculator.calculateNights(checkIn, checkOut);
 18	        assertEquals(2, nights);
 19	
 20	        BigDecimal subtotal = BigDecimal.ZERO;
 21	        for (int i = 0; i < nights; i++) {
 22	            LocalDate nightDate = checkIn.plusDays(i);
 23	            BigDecimal rate = PricingCalculator.calculateNightlyRate(baseRate, nightDate);
 24	            subtotal = subtotal.add(rate);
 25	        }
 26	        subtotal = com.pousadamarealta.util.PriceRounding.round(subtotal);
 27	
 28	        assertEquals(new BigDecimal("599.76"), subtotal);
 29	
 30	        BigDecimal discount = PricingCalculator.calculateDiscount(subtotal, RatePlan.STANDARD);
 31	        assertEquals(BigDecimal.ZERO, discount);
 32	
 33	        BigDecimal total = PricingCalculator.calculateTotal(subtotal, discount);
 34	        assertEquals(new BigDecimal("599.76"), total);
 35	    }
